const payload = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const envelope = payload && typeof payload === 'object' ? payload : {};
const entry = Array.isArray(envelope.entry) ? envelope.entry[0] : null;
const changes = Array.isArray(entry?.changes) ? entry.changes : [];
const candidateValue = changes[0]?.value;
const value = candidateValue && typeof candidateValue === 'object' ? candidateValue : {};
const message = Array.isArray(value.messages) ? value.messages[0] : null;
if (!message || typeof message !== 'object' || !message.id) throw new Error('Message WhatsApp entrant absent ou sans identifiant.');
const contact = Array.isArray(value.contacts) ? value.contacts[0] : null;
const textCandidates = [message.text?.body, message.button?.text, message.button?.payload, message.interactive?.button_reply?.title, message.interactive?.list_reply?.title, message.image?.caption, message.document?.caption];
const texte_message = String(textCandidates.find(candidate => typeof candidate === 'string' && candidate.trim()) || '[Message non textuel]');
const expediteur = String(message.from || contact?.wa_id || '').replace(/\D/g, '');
if (!/^\d{7,15}$/.test(expediteur)) throw new Error('Numéro WhatsApp expéditeur absent ou invalide.');
const nom_expediteur = String(contact?.profile?.name || '');
const message_id = String(message.id);
const timestamp = String(message.timestamp || '');
const referenceSource = String(envelope.ref_mission || envelope.reference_mission || envelope.reference || '') + '\n' + texte_message;
const referenceMatch = referenceSource.match(/=?\s*(MIS-2026-\d{4})/i);
const ref_mission = referenceMatch ? referenceMatch[1].replace(/[=\s]/g, '').toUpperCase() : '';
const isOptionB = /option[\s_-]*b|arbitrage\s*terrain|expert\s*terrain/i.test(texte_message);
const timestampSeconds = Number(timestamp);
const date_reception_utc = Number.isFinite(timestampSeconds) && timestampSeconds > 0 ? new Date(timestampSeconds * 1000).toISOString() : new Date().toISOString();
const type_message = String(message.type || 'unknown');
const routing_context = { numero_whatsapp: expediteur, nom_expediteur, reference_mission: ref_mission, option_b_requested: isOptionB, message_id_parent: String(message.context?.id || ''), type_message, timestamp };
return { json: { expediteur, nom_expediteur, texte_message, message_id, timestamp, numero_whatsapp: expediteur, ref_mission, reference_mission: ref_mission, type_message, contenu: texte_message, date_reception_utc, isOptionB, routing_context } };
